// Defensive guard for schedules created before stable approval IDs existed.
// Group old time-bearing IDs and new stable IDs by source/date/occurrence, then
// retain only the most recently reviewed approved row.
const latest = new Map();
for (const item of items) {
  const n = item.json;
  if (n.status !== 'approved' || !String(n.nudge_id || '').startsWith('schd_')) continue;
  const id = String(n.nudge_id);
  const oldMatch = id.match(/^(schd_.+_\d{8})_\d{4}_(\d+)$/);
  const stableMatch = id.match(/^(schd_.+_\d{8})_(\d+)$/);
  const key = oldMatch ? oldMatch[1] + '_' + oldMatch[2] : stableMatch ? stableMatch[1] + '_' + stableMatch[2] : id;
  const previous = latest.get(key);
  if (!previous || String(n.reviewed_at || '') >= String(previous.json.reviewed_at || '')) latest.set(key, item);
}
return [...latest.values()];

// Select generated delivery rows due in the current five-minute Melbourne window.
// Source review rows never start with schd_ and must not be sent. The narrow
// window prevents an activation or restart from flushing an overdue backlog.
const ACTIONABLE_NUDGE_TYPES = ['reminder', 'challenge'];
const isEnabled = v => ['true', 'yes', '1', 'on'].includes(String(v == null ? '' : v).trim().toLowerCase());

const users = $('Aggregate Users').first().json.users;
const userById = new Map(users.map(u => [String(u.user_id), u]));
const now = $now.setZone('Australia/Melbourne');
const today = now.toISODate();
const phoneRe = /^\+[1-9]\d{7,14}$/;

return items.flatMap(item => {
  const n = item.json;
  if (n.status !== 'approved' || !String(n.nudge_id || '').startsWith('schd_')) return [];
  if (n.scheduled_date !== today || !/^([01]\d|2[0-3]):[0-5]\d$/.test(String(n.scheduled_time || ''))) return [];
  const scheduled = now.startOf('day').plus({ minutes: Number(n.scheduled_time.slice(0, 2)) * 60 + Number(n.scheduled_time.slice(3, 5)) });
  const ageMinutes = now.diff(scheduled, 'minutes').minutes;
  if (ageMinutes < 0 || ageMinutes >= 5) return [];

  const user = userById.get(String(n.user_id));
  if (!user || user.user_status !== 'active') return [];
  const phone = String(user.phone || '').trim();
  if (!phoneRe.test(phone)) throw new Error('Invalid or missing E.164 phone for user_id ' + n.user_id);
  if (!String(n.message_body || '').trim()) throw new Error('Missing message_body for nudge_id ' + n.nudge_id);

  // Two-stage only when the clinician turned it on AND the nudge actually asks
  // the patient to do something. An informational message keeps the single-stage
  // prompt, so it never requests a commitment or arms a follow-up.
  const delayRaw = String(n.followup_delay_hours == null ? '' : n.followup_delay_hours).trim();
  const delayOk = /^\d+$/.test(delayRaw) && Number(delayRaw) >= 1 && Number(delayRaw) <= 72;
  const twoStage = isEnabled(n.followup_enabled) && ACTIONABLE_NUDGE_TYPES.includes(String(n.nudge_type || '')) && delayOk;
  if (isEnabled(n.followup_enabled) && ACTIONABLE_NUDGE_TYPES.includes(String(n.nudge_type || '')) && !delayOk) {
    throw new Error('followup_enabled is TRUE but followup_delay_hours is invalid for nudge_id ' + n.nudge_id);
  }

  return [{ json: {
    ...n,
    recipient_phone: phone,
    recipient_name: user.name || '',
    schedule_id: 'sch_' + n.nudge_id,
    two_stage: twoStage,
    followup_delay_hours: twoStage ? delayRaw : '',
    followup_enabled_normalized: twoStage ? 'TRUE' : 'FALSE'
  } }];
});

// Build a Twilio Content API quick-reply request for each due nudge.
// A two-stage nudge uses the Yes/No commitment template; everything else keeps
// the existing Done / In progress / Not yet template unchanged.
const sid = String($env.TWILIO_ACCOUNT_SID || '').trim();
const token = String($env.TWILIO_AUTH_TOKEN || '').trim();
const from = String($env.TWILIO_WHATSAPP_FROM || '').trim();
const contentSid = String($env.TWILIO_CONTENT_SID || '').trim();
const commitmentSid = String($env.TWILIO_COMMITMENT_CONTENT_SID || '').trim();
const sidRe = /^HX[a-fA-F0-9]{32}$/;
if (!sid || !token) throw new Error('Missing Twilio account credentials');
if (!/^whatsapp:\+[1-9]\d{7,14}$/.test(from)) throw new Error('TWILIO_WHATSAPP_FROM must use whatsapp:+E164 format');
// Each template SID is required only when a nudge in this batch actually needs
// it. A batch of purely two-stage nudges must not be blocked by a missing
// single-stage SID, and vice versa — otherwise one unused variable takes down
// deliveries that never reference it.
if (items.some(i => !i.json.two_stage) && !sidRe.test(contentSid)) {
  throw new Error('A single-stage nudge is due but TWILIO_CONTENT_SID is missing or invalid');
}
if (items.some(i => i.json.two_stage) && !sidRe.test(commitmentSid)) {
  throw new Error('A nudge has the outcome follow-up enabled but TWILIO_COMMITMENT_CONTENT_SID is missing or invalid');
}
const authorization = 'Basic ' + Buffer.from(sid + ':' + token).toString('base64');
const encodeForm = pairs => pairs.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');

return items.map(item => {
  const n = item.json;
  const contentVariables = JSON.stringify({
    1: String(n.recipient_name || 'there').trim() || 'there',
    2: String(n.message_body || '').trim()
  });
  const pairs = [
    ['From', from],
    ['To', 'whatsapp:' + n.recipient_phone],
    ['ContentSid', n.two_stage ? commitmentSid : contentSid],
    ['ContentVariables', contentVariables]
  ];
  return { json: { ...n, twilio_url: 'https://api.twilio.com/2010-04-01/Accounts/' + sid + '/Messages.json', twilio_authorization: authorization, twilio_form: encodeForm(pairs), twilio_mode: n.two_stage ? 'commitment' : 'quick_reply' } };
});

// Merge Twilio responses back into their original nudge rows and, for a
// two-stage nudge, compute when its outcome check becomes due.
const requests = $('Build Twilio Requests').all();
const now = $now.setZone('Australia/Melbourne');
const sentAt = now.toISO();

return items.map((responseItem, i) => {
  const request = requests[i] ? requests[i].json : {};
  const response = responseItem.json || {};
  if (!response.sid) throw new Error('Twilio response missing Message SID for nudge_id ' + request.nudge_id);

  // The due time is anchored once, here, to the send timestamp — delivered_at is
  // preferred but stays blank until delivery-status callbacks exist. Anchoring at
  // delivery rather than at the patient's Yes is what makes a late Yes eligible
  // immediately instead of restarting the clock.
  const twoStage = request.two_stage === true;
  const dueAt = twoStage ? now.plus({ hours: Number(request.followup_delay_hours) }).toISO() : '';

  return { json: {
    ...request,
    wa_message_id: response.sid,
    twilio_status: response.status || 'queued',
    twilio_error_code: response.error_code || '',
    sent_at: sentAt,
    state_status: twoStage ? 'awaiting_commitment' : 'sent',
    followup_due_at: dueAt
  } };
});
